I'm using custom hardware, but I just created this board file for the STM32L476 Nucleo board:

[board.overlay.nucleol476rg.txt](https://github.com/zephyrproject-rtos/zephyr/files/6280990/board.overlay.nucleol476rg.txt)

#define KSCAN_DEV_NAME DT_LABEL( DT_ALIAS( kscan0 ) )
#include <drivers/kscan.h>

static void kscan_callback( const struct device* dev, uint32_t x, uint32_t y, bool pressed )
{
    LOG_INF( "%d, %d, %d.", x, y, pressed );
}

void main(void)
{
    const struct device* kscan_dev = device_get_binding( KSCAN_DEV_NAME );
    kscan_config( kscan_dev, kscan_callback );
    kscan_enable_callback( kscan_dev );
}
